import {
  Marked,
  Renderer,
  type Token,
  type TokenizerAndRendererExtension,
  type Tokens,
} from "marked";

/**
 * Markdown to HTML for the reader. The text comes from scraped web pages, so nothing the page
 * wrote is trusted: raw HTML is reduced to plain text, and link and image addresses must use a
 * known scheme. Everything else in the output is generated by marked from Markdown syntax.
 */

const LINK_SCHEMES = ["http", "https", "mailto"];
const IMAGE_SCHEMES = ["http", "https"];

export function escapeHtml(text: string): string {
  return text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

/** Characters a browser skips when it reads a scheme: controls, whitespace, zero-width marks. */
function isIgnoredInScheme(ch: string): boolean {
  const code = ch.charCodeAt(0);
  return (
    code <= 0x20 ||
    (code >= 0x7f && code <= 0x9f) ||
    (code >= 0x200b && code <= 0x200d) ||
    code === 0x2028 ||
    code === 0x2029 ||
    code === 0xfeff
  );
}

/**
 * Returns the address when it is safe to put in an href or src, else null. Browsers ignore
 * whitespace and control characters inside a scheme ("java\tscript:"), so those are removed
 * before the scheme is read. Relative paths mean nothing in the app and are refused; `#` anchors
 * are only for links (footnotes).
 */
export function safeUrl(
  href: string | null | undefined,
  schemes: ReadonlyArray<string>,
  allowAnchor = false,
): string | null {
  const url = (href ?? "").trim();
  const compact = Array.from(url)
    .filter((ch) => !isIgnoredInScheme(ch))
    .join("");
  if (!compact) return null;
  if (compact.startsWith("#")) return allowAnchor ? compact : null;
  const scheme = /^([a-z][a-z0-9+.-]*):/i.exec(compact);
  if (!scheme || !schemes.includes((scheme[1] ?? "").toLowerCase())) return null;
  return url;
}

export function safeLinkUrl(href: string | null | undefined): string | null {
  return safeUrl(href, LINK_SCHEMES, true);
}

export function safeImageUrl(href: string | null | undefined): string | null {
  return safeUrl(href, IMAGE_SCHEMES);
}

function isMp4Url(url: string): boolean {
  try {
    return new URL(url, "https://placeholder.invalid").pathname.toLowerCase().endsWith(".mp4");
  } catch {
    return false;
  }
}

/** Raw HTML from the page becomes its text. `<br>` stays a line break; script and style go. */
function plainTextOfHtml(raw: string): string {
  if (/^\s*<br\s*\/?>\s*$/i.test(raw)) return "<br>";
  const withoutBlocks = raw
    .replace(/<!--[\s\S]*?-->/g, "")
    .replace(/<(script|style|iframe|object|embed)\b[\s\S]*?<\/\1\s*>/gi, "");
  return escapeHtml(withoutBlocks.replace(/<[^>]*>/g, ""));
}

// Footnotes: `[^1]` in the text, `[^1]: text` below. Per-render state, because marked calls the
// renderers one by one and a reference must know whether its definition exists.
interface FootnoteState {
  defined: Set<string>;
  refCounts: Map<string, number>;
}
let footnotes: FootnoteState = { defined: new Set(), refCounts: new Map() };

/** Ids are built from the label ("76", "a b"), so anything that is not a plain character is hex. */
export function footnoteId(label: string): string {
  return label.replace(/[^A-Za-z0-9_-]/g, (c) => `_${c.charCodeAt(0).toString(16)}`);
}

interface FootnoteDefToken extends Tokens.Generic {
  type: "footnoteDef";
  label: string;
  text: string;
}

interface FootnoteRefToken extends Tokens.Generic {
  type: "footnoteRef";
  label: string;
}

const footnoteDefExtension: TokenizerAndRendererExtension = {
  name: "footnoteDef",
  level: "block",
  start(src) {
    return /^\[\^[^\]\s]+\]:/m.exec(src)?.index;
  },
  tokenizer(src) {
    const match = /^\[\^([^\]\s]+)\]:[ \t]*([^\n]*)((?:\n(?: {2,}|\t)[^\n]*)*)/.exec(src);
    if (!match) return undefined;
    const text = (match[2] + (match[3] ?? "").replace(/\n(?: {2,}|\t)/g, "\n")).trim();
    const token: FootnoteDefToken = {
      type: "footnoteDef",
      raw: match[0],
      label: match[1] ?? "",
      text,
    };
    return token;
  },
  // The definitions are collected and written once, after the body.
  renderer: () => "",
};

const footnoteRefExtension: TokenizerAndRendererExtension = {
  name: "footnoteRef",
  level: "inline",
  start(src) {
    const index = src.indexOf("[^");
    return index === -1 ? undefined : index;
  },
  tokenizer(src) {
    const match = /^\[\^([^\]\s]+)\]/.exec(src);
    if (!match) return undefined;
    const token: FootnoteRefToken = { type: "footnoteRef", raw: match[0], label: match[1] ?? "" };
    return token;
  },
  renderer(token) {
    const { label, raw } = token as FootnoteRefToken;
    if (!footnotes.defined.has(label)) return escapeHtml(raw);
    const count = (footnotes.refCounts.get(label) ?? 0) + 1;
    footnotes.refCounts.set(label, count);
    const id = footnoteId(label);
    const refId = count === 1 ? `fnref-${id}` : `fnref-${id}-${count}`;
    return `<sup class="fn-ref"><a id="${refId}" href="#fn-${id}">[${escapeHtml(label)}]</a></sup>`;
  },
};

/**
 * Where a removable block sits in the Markdown it was rendered from. The reader asks for these
 * (`renderMarkdown(text, { sourceMap: true })`) so a paragraph, heading, list item, quote, code
 * block or table on screen can be cut out of the source text.
 */
export const SOURCE_SPAN_ATTR = "data-sf-src";

export interface BlockSpan {
  /** Offsets into the Markdown: `[start, end)` is the block's own text, markers included. */
  start: number;
  end: number;
  token: Token;
}

const spans = new WeakMap<object, BlockSpan>();

const SPAN_TYPES = new Set(["paragraph", "heading", "blockquote", "code", "table", "hr"]);

/**
 * The spans of the top-level blocks and of the items of top-level lists. Blocks nested in quotes
 * or in list items are left out: marked strips their indentation and `>` marks, so their text
 * does not sit at one place in the source. Empty when the tokens don't add up to the Markdown.
 */
export function mapBlockSpans(tokens: Token[], markdown: string): BlockSpan[] {
  const found: BlockSpan[] = [];
  let pos = 0;
  for (const token of tokens) {
    if (markdown.slice(pos, pos + token.raw.length) !== token.raw) return [];
    if (SPAN_TYPES.has(token.type)) {
      found.push({ start: pos, end: pos + token.raw.length, token });
    } else if (token.type === "list") {
      let at = pos;
      for (const item of (token as Tokens.List).items) {
        if (markdown.slice(at, at + item.raw.length) !== item.raw) break;
        found.push({ start: at, end: at + item.raw.length, token: item });
        at += item.raw.length;
      }
    }
    pos += token.raw.length;
  }
  return pos === markdown.length ? found : [];
}

function withSpan(html: string, token: object): string {
  const span = spans.get(token);
  if (!span) return html;
  return html.replace(/^<([a-z0-9]+)/i, `<$1 ${SOURCE_SPAN_ATTR}="${span.start}-${span.end}"`);
}

const marked = new Marked({ gfm: true, breaks: true, async: false });
marked.use({
  extensions: [footnoteDefExtension, footnoteRefExtension],
  renderer: {
    // The spans exist only for a render that asked for them, so other renders are unchanged.
    paragraph(token) {
      return withSpan(Renderer.prototype.paragraph.call(this, token), token);
    },
    heading(token) {
      return withSpan(Renderer.prototype.heading.call(this, token), token);
    },
    listitem(token) {
      return withSpan(Renderer.prototype.listitem.call(this, token), token);
    },
    blockquote(token) {
      return withSpan(Renderer.prototype.blockquote.call(this, token), token);
    },
    code(token) {
      return withSpan(Renderer.prototype.code.call(this, token), token);
    },
    table(token) {
      return withSpan(Renderer.prototype.table.call(this, token), token);
    },
    hr(token) {
      return withSpan(Renderer.prototype.hr.call(this, token), token);
    },
    html(token) {
      return plainTextOfHtml(token.text);
    },
    link({ href, title, tokens }) {
      const text = this.parser.parseInline(tokens);
      const safe = safeLinkUrl(href);
      if (!safe) return text;
      const titleAttr = title ? ` title="${escapeHtml(title)}"` : "";
      return `<a href="${escapeHtml(safe)}"${titleAttr}>${text}</a>`;
    },
    image({ href, title, text }) {
      const safe = safeImageUrl(href);
      if (!safe) return escapeHtml(text);
      if (isMp4Url(safe)) {
        return `<video src="${escapeHtml(safe)}" autoplay loop muted playsinline></video>`;
      }
      const titleAttr = title ? ` title="${escapeHtml(title)}"` : "";
      return `<img src="${escapeHtml(safe)}" alt="${escapeHtml(text)}"${titleAttr} loading="lazy" decoding="async" referrerpolicy="no-referrer">`;
    },
  },
});

function footnoteList(defs: FootnoteDefToken[]): string {
  const seen = new Set<string>();
  const items: string[] = [];
  for (const def of defs) {
    if (seen.has(def.label)) continue;
    seen.add(def.label);
    const id = footnoteId(def.label);
    const back = footnotes.refCounts.has(def.label)
      ? ` <a class="fn-back" href="#fnref-${id}" aria-label="Back to the text">↩</a>`
      : "";
    const text = marked.parseInline(def.text) as string;
    items.push(
      `<li id="fn-${id}"><span class="fn-label">[${escapeHtml(def.label)}]</span> <span class="fn-text">${text}</span>${back}</li>`,
    );
  }
  return items.length > 0 ? `<ul class="footnotes">${items.join("")}</ul>` : "";
}

/** The Markdown as tokens, with the footnote syntax of the reader. */
export function lexMarkdown(markdown: string): Token[] {
  return marked.lexer(markdown);
}

/** Labels of the footnotes that have a definition (their references render as `[label]`). */
export function definedFootnotes(tokens: Token[]): Set<string> {
  return new Set(
    tokens.filter((t): t is FootnoteDefToken => t.type === "footnoteDef").map((d) => d.label),
  );
}

export interface RenderOptions {
  /** Mark each removable block with `data-sf-src="start-end"` (see `SOURCE_SPAN_ATTR`). */
  sourceMap?: boolean;
}

export function renderMarkdown(markdown: string, options: RenderOptions = {}): string {
  const tokens = marked.lexer(markdown);
  const defs = tokens.filter((t): t is FootnoteDefToken => t.type === "footnoteDef");
  footnotes = { defined: new Set(defs.map((d) => d.label)), refCounts: new Map() };
  if (options.sourceMap) {
    for (const span of mapBlockSpans(tokens, markdown)) spans.set(span.token, span);
  }
  const html = marked.parser(tokens);
  return html + footnoteList(defs);
}
